   "svg": "<svg viewBox=\"0 0 640 250\" role=\"img\" aria-label=\"Comparación: en la gráfica posición-tiempo el MRU es una recta y el MRUA una curva; en la gráfica velocidad-tiempo el MRU es una recta horizontal y el MRUA una recta inclinada\">\n      <rect width=\"640\" height=\"250\" rx=\"16\" fill=\"var(--paper)\"/>\n      <path d=\"M60 40 V 210 H 310\" stroke=\"var(--muted)\" stroke-width=\"2.5\" fill=\"none\"/><text x=\"185\" y=\"30\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"var(--ink)\" font-family=\"Baloo 2, sans-serif\">posición-tiempo (x-t)</text><path d=\"M370 40 V 210 H 620\" stroke=\"var(--muted)\" stroke-width=\"2.5\" fill=\"none\"/><text x=\"495\" y=\"30\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"var(--ink)\" font-family=\"Baloo 2, sans-serif\">velocidad-tiempo (v-t)</text>\n      <line x1=\"60\" y1=\"210\" x2=\"300\" y2=\"90\" stroke=\"var(--pen)\" stroke-width=\"3.5\"/><path d=\"M60 210 Q 200 200 300 60\" stroke=\"var(--red)\" stroke-width=\"3.5\" fill=\"none\"/>\n      <line x1=\"370\" y1=\"140\" x2=\"610\" y2=\"140\" stroke=\"var(--pen)\" stroke-width=\"3.5\"/><line x1=\"370\" y1=\"210\" x2=\"600\" y2=\"60\" stroke=\"var(--red)\" stroke-width=\"3.5\"/>\n      <text x=\"170\" y=\"128\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"var(--pen)\" font-family=\"Atkinson Hyperlegible, sans-serif\">MRU</text><text x=\"296\" y=\"50\" text-anchor=\"end\" font-size=\"15\" font-weight=\"700\" fill=\"var(--red)\" font-family=\"Atkinson Hyperlegible, sans-serif\">MRUA</text><text x=\"590\" y=\"162\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"var(--pen)\" font-family=\"Atkinson Hyperlegible, sans-serif\">MRU</text><text x=\"552\" y=\"72\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"var(--red)\" font-family=\"Atkinson Hyperlegible, sans-serif\">MRUA</text>\n      <text x=\"310\" y=\"236\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"700\" fill=\"var(--muted)\" font-family=\"Atkinson Hyperlegible, sans-serif\">t</text><text x=\"620\" y=\"236\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"700\" fill=\"var(--muted)\" font-family=\"Atkinson Hyperlegible, sans-serif\">t</text>\n    </svg>"
