  "mapa": "<svg viewBox=\"0 0 700 300\" role=\"img\" aria-label=\"Mapa mental: ESTADOS Y GASES\">\n    <g font-family=\"Atkinson Hyperlegible, sans-serif\" font-size=\"15\">\n      <g stroke=\"var(--line)\" stroke-width=\"3\"><path d=\"M350 150 L 140 60\"/><path d=\"M350 150 L 560 60\"/><path d=\"M350 150 L 140 240\"/><path d=\"M350 150 L 560 240\"/></g>\n      <rect x=\"225\" y=\"122\" width=\"250\" height=\"56\" rx=\"28\" fill=\"var(--eso)\"/>\n      <text x=\"350\" y=\"157\" text-anchor=\"middle\" font-size=\"19.0\" font-weight=\"700\" fill=\"#fff\" font-family=\"Baloo 2, sans-serif\">ESTADOS Y GASES</text>\n      <rect x=\"-10\" y=\"34\" width=\"300\" height=\"56\" rx=\"10\" fill=\"var(--card)\" stroke=\"var(--pen)\" stroke-width=\"2\"/>\n      <text x=\"140\" y=\"56\" text-anchor=\"middle\" font-weight=\"700\" fill=\"var(--pen)\">Estados</text>\n      <text x=\"140\" y=\"76\" text-anchor=\"middle\" fill=\"var(--ink)\" font-size=\"13\">sólido · líquido · gas · plasma</text><rect x=\"410\" y=\"34\" width=\"300\" height=\"56\" rx=\"10\" fill=\"var(--card)\" stroke=\"var(--leaf)\" stroke-width=\"2\"/>\n      <text x=\"560\" y=\"56\" text-anchor=\"middle\" font-weight=\"700\" fill=\"var(--leaf)\">Modelo</text>\n      <text x=\"560\" y=\"76\" text-anchor=\"middle\" fill=\"var(--ink)\" font-size=\"13\">teoría cinético-molecular</text><rect x=\"-10\" y=\"214\" width=\"300\" height=\"56\" rx=\"10\" fill=\"var(--card)\" stroke=\"var(--red)\" stroke-width=\"2\"/>\n      <text x=\"140\" y=\"236\" text-anchor=\"middle\" font-weight=\"700\" fill=\"var(--red)\">Cambios</text>\n      <text x=\"140\" y=\"256\" text-anchor=\"middle\" fill=\"var(--ink)\" font-size=\"13\">fusión · vaporización · sublimación</text><rect x=\"410\" y=\"214\" width=\"300\" height=\"56\" rx=\"10\" fill=\"var(--card)\" stroke=\"#b8860b\" stroke-width=\"2\"/>\n      <text x=\"560\" y=\"236\" text-anchor=\"middle\" font-weight=\"700\" fill=\"#b8860b\">Leyes</text>\n      <text x=\"560\" y=\"256\" text-anchor=\"middle\" fill=\"var(--ink)\" font-size=\"13\">Boyle · Charles · Gay-Lussac</text>\n    </g></svg>"
