   "<svg viewBox=\"0 0 260 180\" role=\"img\" aria-label=\"Gráfica de solubilidad: la del azúcar y la sal sube con la temperatura y la del oxígeno baja\"><rect width=\"260\" height=\"180\" rx=\"14\" fill=\"var(--paper)\"/>\n        <path d=\"M40 16 V 150 H 246\" stroke=\"var(--muted)\" stroke-width=\"2\" fill=\"none\"/>\n        <text x=\"246\" y=\"168\" text-anchor=\"end\" font-size=\"10\" font-weight=\"700\" fill=\"var(--muted)\" font-family=\"Atkinson Hyperlegible, sans-serif\">temperatura</text><text x=\"44\" y=\"14\" text-anchor=\"start\" font-size=\"10\" font-weight=\"700\" fill=\"var(--muted)\" font-family=\"Atkinson Hyperlegible, sans-serif\">solubilidad</text>\n        <path d=\"M40 110 Q 140 90 236 26\" stroke=\"var(--red)\" stroke-width=\"3\" fill=\"none\"/><text x=\"176\" y=\"36\" text-anchor=\"end\" font-size=\"10\" font-weight=\"700\" fill=\"var(--red)\" font-family=\"Atkinson Hyperlegible, sans-serif\">azúcar</text>\n        <path d=\"M40 100 L 236 92\" stroke=\"#b8860b\" stroke-width=\"3\" fill=\"none\"/><text x=\"236\" y=\"84\" text-anchor=\"end\" font-size=\"10\" font-weight=\"700\" fill=\"#b8860b\" font-family=\"Atkinson Hyperlegible, sans-serif\">sal</text>\n        <path d=\"M40 60 Q 120 110 236 136\" stroke=\"var(--inf)\" stroke-width=\"3\" fill=\"none\"/><text x=\"60\" y=\"52\" text-anchor=\"start\" font-size=\"10\" font-weight=\"700\" fill=\"var(--inf)\" font-family=\"Atkinson Hyperlegible, sans-serif\">oxígeno (gas)</text></svg>",
